SELECT percentile_cont(0.9) within GROUP (ORDER BY l.value) AS instability_score, COUNT(DISTINCT CASE WHEN d.drg_mortality = 'Y' THEN l.subject_id END)::FLOAT / NULLIF(COUNT(DISTINCT l.subject_id), 0) AS mortality_rate, AVG(l.los) AS average_length_of_stay, SUM(CASE WHEN d.drg_code IN ('Cr', 'K', 'platelets', 'Hgb', 'whole blood K', 'WBC') THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT l.subject_id), 0) AS specialized_care_rate FROM labevents l JOIN diagnoses_icd d ON l.subject_id = d.subject_id AND l.hadm_id = d.hadm_id WHERE l.subject_id IN (SELECT subject_id FROM male_patients) AND l.subject_id IN (SELECT subject_id FROM high_risk_patients) UNION ALL SELECT percentile_cont(0.9) within GROUP (ORDER BY l.value) AS instability_score, COUNT(DISTINCT CASE WHEN d.drg_mortality = 'Y' THEN l.subject_id END)::FLOAT / NULLIF(COUNT(DISTINCT l.subject_id), 0) AS mortality_rate, AVG(l.los) AS average_length_of_stay, SUM(CASE WHEN d.drg_code IN ('Cr', 'K', 'platelets', 'Hgb', 'whole blood K', 'WBC') THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT l.subject_id), 0) AS specialized_care_rate FROM labevents l JOIN diagnoses_icd d ON l.subject_id = d.subject_id AND l.hadm_id = d.hadm_id WHERE l.subject_id IN (SELECT subject_id FROM male_patients) AND l.subject_id IN (SELECT subject_id FROM high_risk_patients);